const http = this.helpers.httpRequest;
const today = new Date().toISOString().split('T')[0];

const KEYWORDS = [
  'eléctric','electric','energía','energia','iluminación','iluminacion',
  'subestación','subestacion','transformador','generador',
  'redes','cableado','medidores','paneles solares','fotovoltaic',
  'RETIE','montaje','mantenimiento eléctrico',
  'obras civiles','construcción','construccion','adecuación',
  'infraestructura','vías','vias','paviment','alcantarillado',
  'consultoría','consultoria','interventoría','interventoria',
  'diseño','diseno','ingeniería','ingenieria'
];

const url = `https://www.datos.gov.co/resource/jbjy-vk9h.json?$select=nombre_entidad,descripcion_del_proceso,valor_del_contrato,fecha_de_firma,departamento,ciudad,modalidad_de_contratacion,tipo_de_contrato,urlproceso,id_contrato&$where=fecha_de_firma%20%3E=%20'${today}'&$order=fecha_de_firma%20DESC&$limit=20`;

const data = await http({ method:'GET', url });
if (!Array.isArray(data)) return [];

let sent = 0;
for (const item of data) {
  const desc = (item.descripcion_del_proceso || '').toLowerCase();
  const entidad = (item.nombre_entidad || '').toLowerCase();
  const tipo = (item.tipo_de_contrato || '').toLowerCase();
  const searchText = desc + ' ' + entidad + ' ' + tipo;
  const matched = KEYWORDS.filter(kw => searchText.includes(kw.toLowerCase()));

  if (matched.length > 0) {
    const valor = parseInt(item.valor_del_contrato) || 0;
    const valorFmt = new Intl.NumberFormat('es-CO', { style:'currency', currency:'COP', minimumFractionDigits:0 }).format(valor);
    const text = `📋 *Nueva Licitación SECOP*\n\n🏛️ *${item.nombre_entidad}*\n📍 ${item.departamento || ''}, ${item.ciudad || ''}\n📝 ${(item.descripcion_del_proceso || '').substring(0,120)}...\n💰 ${valorFmt}\n📅 ${(item.fecha_de_firma || '').split('T')[0]}\n🏷️ ${item.modalidad_de_contratacion}\n\n🔗 ${item.urlproceso?.url || 'https://community.secop.gov.co/'}\n\n⚡ SECOP Alertas`;

    await http({
      method:'POST',
      url:'http://148.230.90.171:8096/message/sendText/wasapea-7c7a2c6c',
      headers:{ 'apikey':'wasapea-evo-key-2026', 'Content-Type':'application/json' },
      body:{ number:'573106055920', text }
    });
    sent++;
  }
}

return { sent, total: data.length };
